INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('district', 'District', 'Second-order administrative division of India, identified by its LGD (Local Government Directory) district code. The LGD code is the canonical join key; names and census codes are alternate identifiers.', 'join_key', 'reference', NULL, ARRAY['district_lgd_code', 'District Code', 'district_name', 'District Name', 'District', 'DISTRICT', 'DT_CEN_CD', 'Census 2011 Code']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('state', 'State / Union Territory', 'First-order administrative division of India, identified by its LGD state code.', 'join_key', 'reference', NULL, ARRAY['state_lgd_code', 'State Code', 'state_name', 'State Name', 'State', 'ST_CEN_CD', 'report_state_label']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('city', 'City', 'Named city as reported by the data source (e.g. CPCB AQI bulletin). Mapped to a district where it lies in exactly one.', 'join_key', 'reference', NULL, ARRAY['city']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('latitude', 'Latitude', 'Latitude in decimal degrees (WGS84).', 'location', 'reference', 'http://qudt.org/vocab/unit/DEG', ARRAY['lat', 'latitude']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('longitude', 'Longitude', 'Longitude in decimal degrees (WGS84).', 'location', 'reference', 'http://qudt.org/vocab/unit/DEG', ARRAY['lon', 'lng', 'longitude']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('observation_date', 'Date', 'Calendar date (YYYY-MM-DD) the value refers to.', 'time', 'reference', NULL, ARRAY['date', 'last_update']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('aggregation_method', 'Aggregation method', 'How a gridded value was turned into a district value (e.g. area_mean_3_cells, nearest_cell).', 'provenance', 'reference', NULL, ARRAY['method']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('source_dataset', 'Source dataset', 'Identifier of the dataset a row came from.', 'provenance', 'reference', NULL, ARRAY['source_dataset']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('rainfall_daily', 'Daily rainfall', 'Total precipitation over one day, as depth of liquid water in mm.', 'measure', 'climate', 'http://qudt.org/vocab/unit/MilliM', ARRAY['rainfall_mm', 'precipitation', 'precip', 'prectotcorr', 'precipitation_sum', 'rain']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('air_temperature_max_daily', 'Daily maximum air temperature', 'Highest near-surface air temperature over one day, in degrees Celsius.', 'measure', 'climate', 'http://qudt.org/vocab/unit/DEG_C', ARRAY['temp_max_c', 't2m_max', 'temperature_2m_max', 'tmax', 'max_temp']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('air_temperature_min_daily', 'Daily minimum air temperature', 'Lowest near-surface air temperature over one day, in degrees Celsius.', 'measure', 'climate', 'http://qudt.org/vocab/unit/DEG_C', ARRAY['temp_min_c', 't2m_min', 'temperature_2m_min', 'tmin', 'min_temp']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('relative_humidity', 'Relative humidity', 'Near-surface relative humidity (daily mean), in percent.', 'measure', 'climate', 'http://qudt.org/vocab/unit/PERCENT_RH', ARRAY['relative_humidity_pct', 'rh2m', 'relative_humidity_2m_mean', 'rh', 'humidity']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('aqi', 'Air Quality Index (India NAQI)', 'India''s National Air Quality Index (0-500) for a city/station on a day, as published by CPCB.', 'measure', 'environment', 'http://qudt.org/vocab/unit/UNITLESS', ARRAY['aqi', 'AQI', 'aqi_value', 'air_quality_index']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('aqi_category', 'AQI category', 'NAQI band for the AQI value: Good, Satisfactory, Moderate, Poor, Very Poor, Severe.', 'measure', 'environment', NULL, ARRAY['aqi_category', 'air_quality']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('prominent_pollutant', 'Prominent pollutant', 'Pollutant(s) driving the day''s AQI (e.g. PM2.5, PM10, O3).', 'measure', 'environment', NULL, ARRAY['prominent_pollutant_raw', 'prominent_pollutant', 'pollutant_id']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('aqi_stations_reporting', 'Stations reporting', 'Monitoring stations that reported / total stations in the city, e.g. ''6/6''.', 'provenance', 'environment', NULL, ARRAY['stations_participated_total']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('pm25_concentration', 'PM2.5 concentration', 'Mass concentration of particulate matter <= 2.5 um in ambient air, in ug/m3.', 'measure', 'environment', 'http://qudt.org/vocab/unit/MicroGM-PER-M3', ARRAY['pm25', 'pm2_5', 'pm2.5', 'PM2.5', 'pollutant_id=PM2.5 / avg_value']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('pm10_concentration', 'PM10 concentration', 'Mass concentration of particulate matter <= 10 um in ambient air, in ug/m3.', 'measure', 'environment', 'http://qudt.org/vocab/unit/MicroGM-PER-M3', ARRAY['pm10', 'PM10', 'pollutant_id=PM10 / avg_value']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_energy_met_daily', 'Electricity energy met (daily)', 'Electrical energy supplied to consumers in a state over one day, in MU (million units = GWh).', 'measure', 'energy', 'http://qudt.org/vocab/unit/GigaW-HR', ARRAY['energy_met_mu', 'energy_met', 'energy_consumption_mu']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_peak_demand_met', 'Peak electricity demand met', 'Maximum electrical demand served in a state on a day, in MW.', 'measure', 'energy', 'http://qudt.org/vocab/unit/MegaW', ARRAY['max_demand_met_mw', 'peak_demand_mw', 'peak_demand_met']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_shortage_at_peak', 'Shortage at peak demand', 'Demand not served at the time of daily peak, in MW.', 'measure', 'energy', 'http://qudt.org/vocab/unit/MegaW', ARRAY['shortage_at_max_demand_mw', 'peak_shortage_mw']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_energy_shortage_daily', 'Electricity energy shortage (daily)', 'Electrical energy demanded but not supplied in a state over one day, in MU (GWh).', 'measure', 'energy', 'http://qudt.org/vocab/unit/GigaW-HR', ARRAY['energy_shortage_mu', 'energy_shortage']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_drawal_schedule_daily', 'Scheduled grid drawal (daily)', 'Electrical energy a state was scheduled to draw from the inter-state grid over one day, in MU (GWh).', 'measure', 'energy', 'http://qudt.org/vocab/unit/GigaW-HR', ARRAY['drawal_schedule_mu']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('electricity_overdrawal_daily', 'Grid over/under-drawal (daily)', 'Actual minus scheduled drawal from the inter-state grid over one day, in MU (GWh); negative = under-drawal.', 'measure', 'energy', 'http://qudt.org/vocab/unit/GigaW-HR', ARRAY['overdrawal_mu']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('anaemia_women_15_49_pct', 'Anaemia prevalence, women 15-49', 'Percent of women aged 15-49 who are anaemic (survey estimate, e.g. NFHS).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['All women age 15-49 years who are anaemic (%)', 'anaemia_women', 'women_anaemic_pct']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('anaemia_children_6_59m_pct', 'Anaemia prevalence, children 6-59 months', 'Percent of children aged 6-59 months who are anaemic (survey estimate, e.g. NFHS).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['Children age 6-59 months who are anaemic ', 'Children age 6-59 months who are anaemic (<11.0 g/dl) (%)', 'anaemia_children']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('high_blood_sugar_women_pct', 'High blood sugar, women', 'Percent of women with blood sugar >140 mg/dl or taking medicine to control it (survey estimate).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['Female Blood sugar level  high or very high (>140 mg/dl) or taking medicine to control blood sugar level (%)']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('elevated_bp_women_pct', 'Elevated blood pressure, women', 'Percent of women with elevated blood pressure or taking medicine to control it (survey estimate).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['Female Elevated blood pressure or taking medicine to control blood pressure (%)']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('stunting_under5_pct', 'Stunting, children under 5', 'Percent of children under 5 who are stunted (height-for-age below -2 SD).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['Children under 5 years who are stunted (height for age) (%)', 'stunting', 'stunted_pct']::TEXT[])
INSERT INTO cml_term (term_key, label, definition, category, domain, unit_uri, synonyms) VALUES ('wasting_under5_pct', 'Wasting, children under 5', 'Percent of children under 5 who are wasted (weight-for-height below -2 SD).', 'measure', 'health', 'http://qudt.org/vocab/unit/PERCENT', ARRAY['Children under 5 years who are wasted (weight for height) (%)', 'wasting', 'wasted_pct']::TEXT[])
